28	const BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
38	
39	// Percentages are applied as `amount * percent / 100` rather than
40	// `amount * 1.percent`, so that integer amounts stay exact: 100 * 1.1 is
41	// 110.00000000000001 in binary floating point, while 100 * 10 / 100 is 10.
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type];
46	
47	const withFirstInsuranceSurcharge = (base: number): number =>
48	  base + percentOf(base, FIRST_INSURANCE_SURCHARGE_PERCENT);
49	
50	const BLOCK_SIZE = 3;
51	const BLOCK_BASE_PREMIUM = 60;
52	
53	// Items of the same type are priced together, so a policy is partitioned into
54	// same-type groups before any group pricing rule is applied.
55	const groupByType = (items: Item[]): Item[][] => {
56	  const groupsByType = new Map<string, Item[]>();
57	  for (const item of items) {
58	    const alike = groupsByType.get(item.type) ?? [];
59	    alike.push(item);
60	    groupsByType.set(item.type, alike);
61	  }
62	  return [...groupsByType.values()];
63	};
64	
65	const sumOf = <T>(values: T[], amount: (value: T) => number): number =>
66	  values.reduce((total, value) => total + amount(value), 0);
67	
68	// A building block of exactly 3 alike components is offered at a flat rate.
69	const groupBasePremium = (alike: Item[]): number =>
70	  alike.length === BLOCK_SIZE
71	    ? BLOCK_BASE_PREMIUM
72	    : sumOf(alike, basePremium);
73	
74	const itemsBasePremium = (items: Item[]): number =>
75	  sumOf(groupByType(items), groupBasePremium);
76	
77	const CURSE_SURCHARGE_PERCENT = 50;
78	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
79	const HIGH_ENCHANTMENT_LEVEL = 5;
80	
81	const isHighlyEnchanted = (item: Item): boolean =>
82	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
83	
84	// Item-specific surcharges apply to the base premium of the affected item.
85	// Several can apply to the same item, so they are summed.
86	const itemSurcharges = (item: Item): number => {
87	  const base = basePremium(item);
88	  const curse = item.cursed ? percentOf(base, CURSE_SURCHARGE_PERCENT) : 0;
89	  const enchantment = isHighlyEnchanted(item)
90	    ? percentOf(base, HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
91	    : 0;
92	  return curse + enchantment;
93	};
94	
95	// Policy-wide modifiers adjust the policy base; item-specific surcharges are
96	// computed against each item's own unmodified base. Both are ADDITIVE against
97	// the base rather than compounding, so they are summed side by side and never
98	// nested inside one another.
99	const withPolicyModifiers = (policyBase: number): number =>
100	  withFirstInsuranceSurcharge(policyBase);
101	
102	const policyPremium = (items: Item[]): number =>
103	  withPolicyModifiers(itemsBasePremium(items)) + sumOf(items, itemSurcharges);
104	
105	// Amounts are rounded in the MHPCO's favor: premiums round up.
106	const roundPremium = (amount: number): number => Math.ceil(amount);
107	
108	const quote = (step: Step): StepResult => ({
109	  premium: roundPremium(PROCESSING_FEE + policyPremium(step.items)),
110	});
111	
112	export const runScenario = (scenario: Scenario): ScenarioResults => ({
113	  results: scenario.steps.map(quote),
114	});
